const staticData = $getWorkflowStaticData('global');
const TELEGRAM_BOT_TOKEN = '8556679902:AAGFg5yBUkF_6EtWHgf3TwTlxva0vbhQvVE';
const TELEGRAM_CHAT_ID = '5084875115';
const issues = $input.all().map(i => i.json).filter(Boolean);
const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
if (staticData.last_check_date !== todayStr) {
  staticData.notified_today_done = false;
  staticData.notified_queue_clear = false;
  staticData.last_check_date = todayStr;
}
const since = new Date(Date.now() - 24 * 60 * 60 * 1000);
const doneStatuses = ['closed','released','completed','cancelled'];
const todayNotDone = issues.filter(i => i.created_at && new Date(i.created_at) >= since && !doneStatuses.includes(i.status));
const openNotMichael = issues.filter(i => i.status === 'open' && i.assignee && i.assignee !== 'michael');
async function sendTelegram(text) {
  await helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
    headers: { 'Content-Type': 'application/json' },
    body: { chat_id: TELEGRAM_CHAT_ID, text }
  });
}
const results = [];
if (todayNotDone.length === 0 && !staticData.notified_today_done) {
  await sendTelegram('✅ All issues created in the last 24h are now closed/released/completed.');
  staticData.notified_today_done = true;
  results.push({ condition: 'today_done', sent: true });
} else {
  results.push({ condition: 'today_done', sent: false, remaining: todayNotDone.length, already_notified: !!staticData.notified_today_done });
}
if (openNotMichael.length === 0 && !staticData.notified_queue_clear) {
  await sendTelegram('✅ All open issues not assigned to you have been worked through.');
  staticData.notified_queue_clear = true;
  results.push({ condition: 'queue_clear', sent: true });
} else {
  results.push({ condition: 'queue_clear', sent: false, remaining: openNotMichael.length, already_notified: !!staticData.notified_queue_clear });
}
return results.map(r => ({ json: r }));
